from mylib.constants import ERR_NOT_FOUND, ERR_CONFLICT, ERR_SERVER, MAX_RETRIES
from mylib.base import ApiResponse

def fetch_with_retry(url: str, retries: int = MAX_RETRIES) -> ApiResponse:
    if retries < 0:
        raise ValueError("retries must be >= 0")
    if url == 'http://good':
        return ApiResponse(200, 'ok')
    if url == 'http://conflict':
        return ApiResponse(ERR_CONFLICT)
    return ApiResponse(ERR_NOT_FOUND)

