from typing import List, Tuple

TokenType = str  # 'NUM' | 'OP' | 'LPAREN' | 'RPAREN' | 'EOF'

def tokenize(source: str, strip_whitespace: bool = True) -> List[Tuple[TokenType, str]]:
    """Toy tokenizer. Returns list of (token_type, lexeme) pairs."""
    import re
    tokens: List[Tuple[str,str]] = []
    pos = 0
    while pos < len(source):
        if strip_whitespace and source[pos].isspace():
            pos += 1; continue
        m = re.match(r'\d+', source[pos:])
        if m:
            tokens.append(('NUM', m.group())); pos += len(m.group()); continue
        if source[pos] in '+-*/':
            tokens.append(('OP', source[pos])); pos += 1; continue
        if source[pos] == '(':
            tokens.append(('LPAREN', '(')); pos += 1; continue
        if source[pos] == ')':
            tokens.append(('RPAREN', ')')); pos += 1; continue
        pos += 1
    tokens.append(('EOF', ''))
    return tokens

