from typing import Optional

class VersionStore:
    def __init__(self):
        self._data: dict = {}
        self._version: int = 0

    def get(self, key: str) -> Optional[str]:
        return self._data.get(key)

    def set(self, key: str, value: str, version: int) -> None:
        if version <= self._version:
            raise ValueError(f'version {version} <= current {self._version}')
        self._version = version
        self._data[key] = value

