from dataclasses import dataclass, field
from typing import List, Optional

MAX_DEPTH = 4

@dataclass
class TreeNode:
    value: int
    children: List['TreeNode'] = field(default_factory=list)

def tree_height(node: 'TreeNode') -> int:
    if not node.children:
        return 1
    return 1 + max(tree_height(c) for c in node.children)

def build_tree(values: list, depth: int = 1, branching: int = 2) -> Optional['TreeNode']:
    if not values or depth > MAX_DEPTH:
        return None
    node = TreeNode(value=values[0])
    remaining = values[1:]
    chunk = max(1, len(remaining) // branching) if remaining else 0
    for i in range(branching):
        if not remaining:
            break
        child = build_tree(remaining[:chunk] or remaining[:1], depth + 1, branching)
        if child is not None:
            node.children.append(child)
        remaining = remaining[chunk:] if chunk else remaining[1:]
    return node

