from checksum import compute_checksum
from typing import List

@dataclass
class Chunk:
    data: bytes
    index: int
    checksum: int = field(default=0)

    def __post_init__(self):
        if self.checksum == 0:
            object.__setattr__(self, 'checksum', compute_checksum(self.data))

def process_batch(chunks: List[Chunk]) -> dict:
    valid = sum(1 for c in chunks if compute_checksum(c.data) == c.checksum)
    return {'total': len(chunks), 'valid': valid, 'invalid': len(chunks) - valid}

