from units import Quantity, SI_UNITS

def add_quantities(a: Quantity, b: Quantity) -> Quantity:
    if a.unit != b.unit:
        raise ValueError(f'Unit mismatch: {a.unit} vs {b.unit}')
    return Quantity(value=a.value + b.value, unit=a.unit)

def validate_quantity(q: Quantity) -> bool:
    return q.unit in SI_UNITS

def scale_quantity(q: Quantity, factor: float) -> Quantity:
    if not validate_quantity(q):
        raise ValueError(f'Non-SI unit: {q.unit}')
    return Quantity(value=q.value * factor, unit=q.unit)

