from dataclasses import dataclass
from typing import List, Optional

@dataclass
class Task:
    id: str
    payload: str
    priority: int = 0

class TaskQueue:
    def __init__(self):
        self._tasks: List[Task] = []
        self._ids: set = set()

    def enqueue(self, task: Task) -> None:
        if task.id in self._ids:
            raise ValueError(f'Duplicate task ID: {task.id}')
        self._ids.add(task.id)
        self._tasks.append(task)

    def dequeue(self) -> Optional['Task']:
        if not self._tasks:
            return None
        best_idx = max(range(len(self._tasks)), key=lambda i: self._tasks[i].priority)
        task = self._tasks.pop(best_idx)
        self._ids.discard(task.id)
        return task

def batch_submit(queue: 'TaskQueue', tasks: List[Task]) -> dict:
    submitted = 0
    rejected = 0
    errors: List[str] = []
    for task in tasks:
        try:
            queue.enqueue(task)
            submitted += 1
        except ValueError:
            rejected += 1
            errors.append(task.id)
    return {'submitted': submitted, 'rejected': rejected, 'errors': errors}

