from typing import Callable, Any

def compose(f: Callable, g: Callable) -> Callable:
    """Returns h where h(x) = f(g(x)). Both f and g must be pure."""
    def h(x: Any) -> Any:
        return f(g(x))
    return h

def memoize(fn: Callable) -> Callable:
    # Cache stored as closure default-arg — no module-level mutable state.
    def wrapper(*args, _cache={}) -> Any:
        if args not in _cache:
            _cache[args] = fn(*args)
        return _cache[args]
    return wrapper
